def main() -> int:
    check = "--check" in sys.argv
    root = pathlib.Path(__file__).resolve().parent.parent
    han = re.compile(r"[\u4e00-\u9fff]")
    files = ["agent/tools.go"]
    applied = 0
    for rel in files:
        path = root / rel
        text = path.read_text(encoding="utf-8")
        before = text
        for zh, ko in sorted(PAIRS, key=lambda p: len(p[0]), reverse=True):
            if zh in text:
                text = text.replace(zh, ko)
                applied += 1
        if not check and text != before:
            path.write_text(text, encoding="utf-8")
    print(f"applied {applied} replacements (check={check})")

    leftover = []
    for rel in files:
        path = root / rel
        for i, line in enumerate(path.read_text(encoding="utf-8").split("\n"), 1):
            if line.strip().startswith("//"):
                continue
            for lit in re.findall(r'"((?:[^"\\]|\\.)*)"', line):
                if han.search(lit):
                    leftover.append(f"{rel}:{i}")
    print(f"remaining Chinese literals in {files}: {len(leftover)}")
    for item in leftover[:20]:
        print("  " + item)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
